INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1067149-che309', 'stk-azeezo', 'CHE 309', 'info', '{"desc": "جودة المقرر بشكل عامالمقرر حيل مفيد للي يبي يشوف شنو درس يعني تطبيق للي كنت تدرسه سابقا\n\nياخذ وقت للي يبي يسويه بمصداقية و امانة (صراحة يفيد في الفاينل)\n\nالمواضيع التي يغطيها المقرر مفيدة جدا\nيقسم المقرر الي 3 اقسام\nheat transfer\nmass transfer\nfloud movment\nطبعا كل 5 اسابيع راح تسوي جزئية\nراح تطبق ما تعلمته في 300 و 304 و 204\n\nالكتاب المستخدم للمقررالكتاب مفيد بس تحتاج الى مساعدة المدرس في الحسابات\n\nالأسئلة والأمثلة المستخدمة في المقررلايوجد\nمدى فائدته في الناحية التطبيقية100%", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-309-chemical-engineering-laboratory-i/120655/2", "user": "azeezo", "ts": 1342259993000, "tid": 120655, "pn": 2}}', 1342259993000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1234560-che309', 'stk-chemist', 'CHE 309', 'info', '{"desc": "^^\n🤠\n\nبسم الله الرحمن الرحيم\n\nجودة المقرر بشكل عام:\nممتاز جدا يفيدك بشكل كبير في التدريب الصيفي والتعاوني وكذلك في حياتك المهنية القادمة بإذن الله.\n\nالمواضيع التي يغطيها المقرر:\nالمقرر ينقسم إلى ثلاث أقسام وفي كل قسم تدرس فيه أربع تجارب يختارها منسق المادة.\n\nFluid Mechanics:\nEXPERIMENT No. F2: Flow through Packed Beds EXPERIMENT No. F3: Fluidized Bed\nEXPERIMENT No. F4: Flow Meter Calibration Rig\nEXPERIMENT No. F5: Losses in Piping Systems\nEXPERIMENT No. F8: Pumps characteristics\n\nHeat Transfer:\nEXPERIMENT No. H1: Heat Transfer by Conduction\nEXPERIMENT No. H2: Combined convection and radiation heat transfer\nEXPERIMENT No. H4: Heat Transfer in a Double\nPipe Heat Exchanger\nEXPERIMENT No. H6: Heat Transfer in a Shell and Tube Heat Exchanger\nEXPERIMENT No. H7: Heat Transfer by Free and Forced Convection\nEXPERIMENT No. H8: Computer Linked Cross Flow\nHeat Exchanger\n\nMass Transfer:\nEXPERIMENT No. M1: Molecular Diffusion in Gases\nEXPERIMENT No. M2: Physical Gas Absorption in a Packed-Column Absorber\nEXPERIMENT No: M5: Effect of Agitation on Solid Liquid MassTransfer\nEXPERIMENT No. M8: Drying of Solids\n\nطبعا كل أربع أسابيع تخلصون قسم من الأقسام والريبورتات تقدمها بعد دراسة التجربة بإسبوعين يعني معنى ذلك انك مو كل تجربة تكتب لها ريبورت ولكن معنى ذلك هو أن كل قسم تكتب فيه ريبورتين عن فقط تجربتين من 4 تجارب يختارها لك المدرس يعني راح يكون مجموع الريبورتات في المادة 6 ريبورتات من أصل 12 تجربة.\n\nفي كل تجربة لازم تسوي لها “Sample Calculation” وتسلمها في الإسبوع اللي بعده يعني راح يكون عندك 12 سامبل كالكوليشن\n\nال سامبل كالكوليشن مفيدة جدا جدا في الفاينال فلا تحلها إلا وانت فاهمها صح علشان ما تتعب في الفاينال.\n\nتقسيم الدرجات للمادة:\nAttendence of Safety Lec = 2%\nCalculation Hours = 4%\nQuizess = 6%\nOral Presentation = 8%\nSix Reports = 25%\nOral Exam = 15%\nFinal Exam = 40%\nTotal 100%\n\nأ) Safety Lec\nتكون في ثاني يوم لاب لأن أول الأيام مافيه لابات\n\nب) الكويزات\nوتكون قبل كل تجربة وعادة تتكلم عن نظرية التجربة والأجهزة المستخدمة وال Objective\n\nجـ) Oral presentation\nوهو عرض لأحد التجارب اللي سويتها وأيضا كتبت عنها ريبورت وعلشان تجيب درجة كاملة لازم يكون عرضك مكون من:\n\n1) Outline\n2) Introduction\n3) Objective\n4) Brief Description of the Devices\n5) Experimental Procedure\n6) Results\n7) Disscusion of Result\n8) Recommendation\n9) Conclusion\n\nد) Oral Exam\nوهو عبارة عن اختبار شفوي يسألونك عن جميع التجارب اللي سويتها ولازم تكون قارئ الكتاب علشان تذكر وش سويت خصوصا في أول التجارب.\n\nهـ) الفاينال:\nطبعا هو كومن واقدر أقول انه اللي يصنع الفارق لأن أغلب المدرسين بعطون الطلاب درجة كويسة في الريبورتات فركز عليه لأنه مربط الفرس. الفاينال ثلاث أقسام قسم عن الفلويد وقسم عن الماس وقسم عن الهيت. في كل تجربة في القسم عليها أربعة أسئلة إختيارية وفي كل قسم سؤالين طويلين حق الحسابات وتكون عليهم درجه عالية فإذا كنت حال السامبل كالكوليشن كويس وفاهمها صح ماراح تلقى صعوبة بإذن الله.\n\nالكتاب المستخدم للمقرر:\nالكتاب ممتاز من مطابع الجامعة طبعة 2012 يعني جديد ومصحح من الأخطاء.\n\nرأيي في الكورس:\nالكورس مرة مهم ولكن في المقابل فهو فيه كرف مو طبيعي. الريبورت لوده يبيله يوم كامل على ماتكتبه خصوصا أول الريبورتات. فالعتب على القسم اللي مخلى الكورس ساعتين مفروض هذا الكورس ثلاث ساعات من الكرف اللي فيه او خففوا على الطلاب وخلوه ساعتين. أما لا كذا ولاكذا صعبة جدا. وكلمنا الدكتور بخصوص هذا الموضوع فضم وجهة نظرة إلى نظرنا وقال صحيح مفرض ان هذا الكور 3 ساعات. أصلا كيف يدخل هذا الشي في العقل يعني هذا الكورس هو بنفسه يساوي كورس إسلامي. لا مستحيل هذا فيه كرف وتعب والإسلامي مافيه كرف وتعب.\n\nبالتوفيق ياشباب 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-309-chemical-engineering-laboratory-i/120655/3", "user": "Chemist", "ts": 1371102515000, "tid": 120655, "pn": 3}}', 1371102515000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1247592-che309', 'stk-hexane', 'CHE 309', 'info', '{"desc": "ما شاء الله … اخوي Chemist شرح المادة بشكل ممتاز 👍\n\nبس حبيت أدلو بدلوي…\nالكورس هذا أهميته انه بيعطيك الفرصة انك تطبق اللي تعلمته في الكورسات التالية:\nCHE 300\nCHE 204\nCHE 304\n\nفعلا هذي المادة تستاهل 3 ساعات…\nالكورس نفسه أشوفه سهل … لكن صعوبته في الكرف اللي فيه ! (Experiments 12, ريبورتات, إختبارين في نهاية الترم, كوزات) … بس توزع وقتك مزبووط يكون زي العسل\n\n- كل طالب راح يسلّم 6 ريبورتات لـ6 تجارب من بين هالـ12 تجربة\n- بيقسمونكم على شكل قروبات… غالبا كل قروب فيه 3 أشخاص, وتسليم الريبورتات للتجارب بيكون عن طريق التناوب (بحيث كل طالب لازم بس يسلّم 6 تقارير خلال الفصل)\n- راح يكون فيه كوزات في بداية اللاب بيسألكم فيها عن تجربة اليوم (بحسب المدرس وعادة تكون سهلة)\n\nنصيحة يا اخوان:\n\nفي نهاية الترم مثل ما ذكر اخوي كيميست فيه اختبار تحريري شامل على كل اللي درست وقبله الاختبار الشفهي (oral). فـ بيدكم 45 % و الباقي من الاختبار الشفهي (15 %) والنهائي (40 %) فانتبهوا من بعض الأخطاء:\n\n1- نسخ الريبورتات من الـold reports:\nالـold reports فايدتها انك تتعلم طريقة حل المسائل وتفهم كيف تطلّع الـresults … أما انها تُستخدم للنسخ فلا أنصح أبدا أبدا …\nعندهم طريقة يعرفون من اللي يسوي نسخ لصق, أعرف شخصيا 2 اعطوهم 0 في احد ريبورتاتهم لأنهم اكتشفوا انهم نسخوا.\nوبرضو اللي بينسخ راح يحرم نفسه من فهم التجربة < بالعاميّ في الإختبار النهائي بياكل هوا 😆\n\n2- الحضور المتأخر:\nيمكن يفوتك الكوز أو شرح التجربة\n\n3- قروب من 3 أشخاص, 2 شغّالين والثالث جالس يتفرج:\nلازم الكل يشارك في إنجاز التجربة … اللي بيتفرج بيعرف حجم غلطته في اختبار الـOral\n\n4- عدم التحضير الجيّد للـPresentation:\nخذ وقتك في إعداد وترتيب السلايدات … وأهمم شي لازم تتمرن قبلها بيوم او أكثر عشان تقدم العرض بطلاقة\n\nبالتوفيق جميعاً 👍\n\nكلمة أخيرة … الكتاب اللي بيعطونكم اياه لا ترمونه في نهاية الفصل, لأنه مفييد جدا … بحيث انه يعطيك زبدة 3 كورسات في كتاب واحد\nآسف على الإطالة … دعواتكم ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-309-chemical-engineering-laboratory-i/120655/4", "user": "HeXaNe", "ts": 1374445561000, "tid": 120655, "pn": 4}}', 1374445561000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1432511-che309', 'stk-_3111', 'CHE 309', 'info', '{"desc": "شرح الاخوان واضح جدا وما أزيد عليه إلا كم ملاحظة\n1- توقعي أن 80٪ من الطلاب ياخذوا b في المادة\n2- ابعد عن هذه التجارب: m2,m8,h6,f8 من جد أقولك حاول تبعد عنهم ريبورتاتهم طويلة مرة، واحد منهم وصل معي الى 40 صفحة!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-309-chemical-engineering-laboratory-i/120655/6", "user": "_3111", "ts": 1446940187000, "tid": 120655, "pn": 6}}', 1446940187000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467018-che309', 'stk-k_94', 'CHE 309', 'info', '{"desc": "جودة المقرر بشكل عام\n\nمهم جدا وتطبيق عملي للي درسته ب 300,304 , 204 CHE\nالكتاب المستخدم للمقرر\nممتاز جدا ويشرح التجربة بشكل كافي ووافي والdata analysis حقت الريبورت يوضح لك وش يبي منك + الدكتور نفسه يساعدك فيها\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nكله عملي\nمدى فائدته في الناحية التطبيقية\n\nممتاز\n\n----\n\nالصراحة المادة هذي بالرغم من اهميتها الا انها للاسف من اكثر المواد اللي حتتعب فيها ريبورتات توصل فوق 25 صفحه والترم هذا طبقوا فيها Turn it in يعني الله يعينك من جد , معظم الدكاترة اذا تعدت النسبة ال30% يخلون طلابهم يعدلون عليها ما عدا الدكتور كامل الدين محجوب توصل لي 57% ولا يقول شي 😊 …\n\nبس انتبهوا من الفاينل عليه 40% وكل التجارب معك !! , حرام المادة هذي وزنها ساعتين كانها اسلامي وعربي\n\nبالعادة ما يطلعون اسماء الدكاترة قبل بداية الترم لسبب لا اعلمه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-309-chemical-engineering-laboratory-i/120655/9", "user": "K_94", "ts": 1485380776000, "tid": 120655, "pn": 9}}', 1485380776000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486838-che309', 'stk-user9534', 'CHE 309', 'info', '{"desc": "حلوة المادة لأنك بتشوف تخصصك على أرض الواقع\nالريبورتات في البداية متعبة لكن مع الوقت بتتعود، كل طالب بيكتب ٦ ريبورتات خلال السمستر\nالقريد يتحدد بشكل كبير على الفاينل، عليه ٤٠٪ وباقي الدرجات غالباً تكون نورماليزد فلذلك الفاينل هو اللي بيحدد القريد\nالفاينل صعب، من كل تجربة بيجي سؤال فلازم قبل الفاينل بكم يوم تذاكر الكالكوليشن لكل تجربة وخصوصاً التجارب اللي ماكتبت أنت عنها ريبورت\n\nهنا روابط للريبورتات بتساعدكم في الكتابة، لا تنسخ منها لأن بيعطونك صفر لو نسخت\n\n309-2016 - Download - 4shared\n\nريبورتات أخرى\nCHE 309 my - Download - 4shared\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-309-chemical-engineering-laboratory-i/120655/10", "user": "user9534", "ts": 1517082308000, "tid": 120655, "pn": 10}}', 1517082308000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1059515-che309', 'stk-geebeeny', 'CHE 309', 'srcU', '{"html": "هذا ؟؟<br><br>​<span data-fid=\"stk-f1059515-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1059515-0": {"name": "1-Introduction_Introduction.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/lab-che-309-manual/127932/2", "user": "geebeeny", "ts": 1340561109000, "tid": 127932, "pn": 2}}', 1340561109000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9221-che309', 'stk-user9221', 'CHE 309', 'doc', '{"docs": [{"id": "stk-dr-f115334", "n": "Dr. Kamaleldin Mahgoub", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 132 - CHE 309\n\nMr. Kamal-Edin Mahjuob\n\nالتحضير :\nبما إن المادة لاب وفيها كويز لمدة 10 دقايق في بداية كل لاب فلازم تجي On time ولا بيروح عليك الكويز أو جزء من وقته\n\nطريقة الشرح :\nيشرح لك الكونسبت من ورى التجربة وبعدين ينتقل إلى تطبيقاتها في الصناعة ولكن عيبه إنه يتضايق من كثرة الأسئلة ويبغى يعطيك اللي عنده ويمشي للقروب اللي بعدكم لأن في السكشن فيه 4 قروبات وكل قروب بيشتغل على تجربة مختلفة ولازم يشرح لهم كلهم بنفس الوقت\n\nالكويزات :\nنفس الطريقة في كل الكويزات يسألك عن 5 شغلات:\n1. عنوان التجربة (title)\n2. أهداف التجربة (objective)\n3. أجزاء التجربة الأساسية (Main Equipment)\n4. طريقة التجربة (Eperimental Procedure)\n5. فقرتين صح وخطأ (وغالباً الأولى تكون خطأ والثانية صح غالباً).\n\nالمياجر:\nمافي\n\nالفاينلات :\nالفاينل كومون بين كل الدكاترة وجانا حريقة فلذلك يحتاج تستعد كويس\n\nالقريد النهائي:\nأشوفه متساعد نوعاً ما ويهمه إنك تخلص الكورس وأنت فاهم فلذلك أعطيه B+\n\nالصوت:\nاللهجة سودانية قح لكن صوته واضح ومفهوم\n\nإضافات :\n\nالأستاذ كان كووردينتر اللابات لمدة طوييييلة وغيروه قبل سنة ومع ذلك إلى الآن ماسك الخيط والمخيط بالنسبة للابات الهندسة الكيميائية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374891-che309", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kamaleldin-mahgoub/115334/4", "user": "user9221", "ts": 1401530199000, "tid": 115334, "pn": 4}}]}', 1401530199000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-che309', 'stk-k_94', 'CHE 309', 'doc', '{"docs": [{"id": "stk-dr-f115334", "n": "Dr. Kamaleldin Mahgoub", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 161- CHE 309\n\nالتحضير :\nفيه كوز بداية الكلاس يحضر عن طريقه , ما فيه وقت محدد للكوز لو جيت متاخر بكم دقيقه عادي عند الدكتور يعطيك وقت زيادة\n\nطريقة الشرح :\nيسهب في الشرح ويبدا يتكلم عن استخدام النظرية بالصناعه وتطبيقاتها ويهتم كثيييييير بفهم الطالب لا تحاول تسلك له تراه يحجر …\nالكويزات :\n\nنفس ما قال الاخ كميكالاوي واقتبس منه \"\nنفس الطريقة في كل الكويزات يسألك عن 5 شغلات:\n1. عنوان التجربة (title)\n2. أهداف التجربة (objective)\n3. أجزاء التجربة الأساسية (Main Equipment)\n4. طريقة التجربة (Eperimental Procedure)\n5. فقرتين صح وخطأ (وغالباً الأولى تكون خطأ والثانية صح غالباً). \"\n\nالمياجر:\nلا يوجد\n\nالفاينلات :\nكومن وكان على كل التجارب والوقت ابدا مو كافي , الدكتور قال لو قلتوا لي كان مددته ما عندي مشكلة\n\nالقريد النهائي:\n\nمتساعد فيها\nالصوت:\nواضح ومفهوم\n\nإضافات :\nالدكتور بداية الترم كان قاسي بالتعامل ودايما عصبي ويدقق على اتفه الأشياء بالريبورت وبعض الاحيان اذا جبت العيد في جوابك يبدا يتكلم بالجامعه ودكاترتها , لكن صدقني كله لمصلحتك ويهتم كثير لفهمك للكونسبت لكن هو الله يهديه حبه قاسي شوي :in_love: …\n\nالترم هذا لاول مره يطبقون علينا الTurn it in وفيه دكاترة ثانيين يدققون عليه كثيييير واذا تعدى 30% يرجعونه لك تعدل عليه …\n\nالدكتور كامل الدين اثنين ما سلمتهم والبقية نسبتهم 57% وحولها وما يدقق عليها واذا سال اقول له لاني انقل من الكتاب كثير ولا يخليك تكتبه من جديد…\n\nويعطي sample calculation ممتاااااز عشان تمشي عليه بالارقام حقتك وملف اكسل جاهز عندك من ريبورتات قديمه ,\n\nبس يظل الريبورت متعب ولازم تجتهد عليه … يعيب على الدكتور انه ما يسمح بالجوال ابدا قدامه حتى لو التجربة كلها لازم تنتظر , بس هو يقعد ربع ساعه ويروح مكتبه لين تنتهون يعني خذ راحتك وقتها 🤠\n\n-----\n\nاول مره تشوف الدكتور بتقول وش هالمصيبه اللي طحت فيها بس نهاية الترم بتقدر الشي اللي الدكتور كان يسويه فيكم 😁", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467021-che309", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kamaleldin-mahgoub/115334/5", "user": "K_94", "ts": 1485383389000, "tid": 115334, "pn": 5}}]}', 1485383389000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mjehad-che309', 'stk-mjehad', 'CHE 309', 'doc', '{"docs": [{"id": "stk-dr-f118698", "n": "Dr. Nayef Al-Saifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 309- Term 132\n\nالدكتوور في الشرح ما عليه كلااام من أفضل الدكاااترة شرحا\nولكن في ال 309 انت ما تحتاج شرح وأغلب التجارب التكنشن يشرحها لك\nوالدكتور نايف شديد نوعا ما يعني من كثر مو فاهم ما تقدر تسلك له واي تمشي عليه اي شي لازم تكون فاهم صح عشان تجاوب أسئلته\n\nمتساهل نوعا ما في وقت تسليم الريبورت اذا كلمته يعطيك مهلة كم يوم\n\nعامة ما أنصح بدكتور في ال 309 شوف لك تكنشن او طالب PHD أفضل\n\nغير ال 309 و 409 لاااااااااا تنرل الا عند دكتور نايف اذا تقدر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1393535-che309", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nayef-al-saifi/118698/20", "user": "mjehad", "ts": 1409120500000, "tid": 118698, "pn": 20}}]}', 1409120500000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che309', 'stk-chemist', 'CHE 309', 'doc', '{"docs": [{"id": "stk-dr-f118699", "n": "Dr. Osamah Bin-Dahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 309\n\nالتحضير:\nبالكويزات مع كل تجربة\n\nالشرح:\nطبعا مايشرح كل التجارب لأنه في تكنشن يساعده في شرح بعض التجارب. عموما شرحه كويس وفاهم المادة صح ولكن يعيبه كلامه السريع وصوته المنخفض نوعا ما ولا شرحه ماعليه كلام.\n\nالكويزات:\nمع كل تجربه في كويز والكويز سهل يتكلم عن التجربه كامله. وطريقة كويزاته كالتالي:\nQ1\\ What is\\are the objective of this exp\nQ2\\ True or False\nQ3\\ what is the title of this exp\nQ4 Choose the correct answer\nQ5 Write down the devices that is used in this exp\nQ6\\ Write down the equation of ----\n\nالأسئلة اللي بالبنفسجي دايما يجيبها في كل كويز وبعض المرات يكون فيه سؤال رابع يأتي من الأسئلة الباقية وبعض المرات يكتفي بهذه الأسئلة الأساسية.\n\nالمياجر:\nمافيه\n\nالفاينال:\nكومن\n\nالصوت:\nبعض مرات يتكلم بسرعه وصوته المنخفض نوعا.\n\nتصحيحه في الريبورتات:\nحقاني ولا يدقق كثير. هو يقول بنفسه إذا الطالب مسلم كل شي كامل مستحيل ينزل عن 45 من 50 في درجة التقرير.\n\nالأخلاق:\nرهييبه. ماقد مرة شفته معصب أو زعلان من طالب بختصار قمة في الأخلاق والتعاون الله يسعده ويوفقه.\n\nمميزاته:\n1) قمة في الأخلاق والتعاون\n2) مايعسر ولا يدقق كثير على الطالب\n3) سوى شي حلو مرة وهو كما تعلمون ان 309 عبارة عن لابين واحد للحسابات وواحد للتجارب فجمع اللابين مع بعض وصار عندنا اليوم الثاني فاضي 🤠.\n4) عمل لنا أوراق مساعدة في الحسابات فادتني كثيرا في عمل الحسابات وفي الفاينال.\n\nعيوبه:\nالصوت كما ذكرت\n\nالقريد النهائي:\nA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1235065-che309", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-bin-dahman-osamah/118699/3", "user": "Chemist", "ts": 1371263014000, "tid": 118699, "pn": 3}}]}', 1371263014000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11325-che309', 'stk-user11325', 'CHE 309', 'doc', '{"docs": [{"id": "stk-dr-f182525", "n": "Dr. Ahmed Altriki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله بكون اول شخص يقيم احمد التريكي\n\nبنود التقييم : CHE309 لاب كميكال 1\n\nالتحضير : مايحتاج لان بداية كل لاب كويز\nطريقة الشرح : نختبر الكويز ثم يشرح لكل قروب كيف يسوون التجربة ولمن نخلص منها نروح له عشان يشرح لنا كيف نحل الريبورت\nالكويزات : سهلة\nالمياجر: لايوجد\nالفاينلات : سهل لكن طويل مدتها ثلاث ساعات الا ربع\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\nالمهندس احمد التريكي من افضل المدرسين بالقسم من ناحية مساعدة الطلاب ووضوح طريقة التقييم والتصحيح صح ان الكورس سهل لكن واضح انه ماشاء الله مجتهد واعتقد بيبدع مستقبلا لمن يدرس كورسات نظرية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533066-che309", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-altriki/182525/2", "user": "user11325", "ts": 1639645857000, "tid": 182525, "pn": 2}}]}', 1639645857000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unlucky-che309', 'stk-unlucky', 'CHE 309', 'doc', '{"docs": [{"id": "stk-dr-f182525", "n": "Dr. Ahmed Altriki", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che309\nالتحضير : مايحتاج لان بداية كل لاب كويز\nطريقة الشرح : بعد الكويز ينقسم كل قروب ويجي الدكتور او احد مساعديه ويشرح لك، شرحه للداتا اناليسس لا يعلى عليه صراحةً وما يقصر\nالكويزات : سهلة\nالفاينلات : ٦ مسائل ريتن عليها ١٠٨ و٢٤ خيارات كل سؤال ٣. الاختبار متوسط الى سهل لكن لازم تمر على كل التجارب وتعرف كيف تحل، لا تترك حتى تجربة وحده\nالقريد النهائي: A+++++\nالصوت: واضح\nإضافات :\nالدكتور متساهل جدًا بالتصحيح مع الكل ومتعاون ومحترم جدًا، جزاه الله خير الجزاء.\nالكلاس وورك ٣٧ من ٤٣ = ٨٦٪؜ والافرج يكون على حسب الي معك اذا ضايعين بتزيد واذا دوافير بتنزلون.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533218-che309", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-altriki/182525/3", "user": "Unlucky", "ts": 1640933981000, "tid": 182525, "pn": 3}}]}', 1640933981000, 1794826841, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
